export function initInstall(){let prompt=null;const triggers=document.querySelectorAll('.install-trigger');const standalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone;const dialog=document.createElement('dialog');dialog.className='install-dialog';dialog.setAttribute('aria-labelledby','install-title');dialog.innerHTML='<button class="dialog-close" aria-label="Close installation instructions">×</button><h3 id="install-title">Your moment.<br>One tap away.</h3><div id="install-content"></div><button class="button install-done">Got it</button>';document.body.append(dialog);const dismiss=()=>dialog.close();dialog.querySelector('.dialog-close').onclick=dismiss;dialog.querySelector('.install-done').onclick=dismiss;dialog.addEventListener('click',e=>{if(e.target===dialog)dismiss()});const update=()=>triggers.forEach(b=>{b.hidden=!!standalone()});update();window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e;update()});window.addEventListener('appinstalled',()=>{prompt=null;update();if(dialog.open)dialog.close()});triggers.forEach(button=>button.addEventListener('click',async()=>{if(prompt){await prompt.prompt();await prompt.userChoice;prompt=null;return}const ios=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);dialog.querySelector('#install-content').innerHTML=ios?'<p>Add Madero Slim to your iPhone or iPad home screen:</p><ol><li>Open this website in Safari.</li><li>Tap Share, then Add to Home Screen.</li><li>Tap Add to keep your wellness rituals close.</li></ol>':'<p>Install from a supported browser on HTTPS:</p><ol><li>Open your browser menu.</li><li>Choose Install app or Add to home screen.</li><li>If the option is missing, revisit after opening the website online, or use Chrome or Edge.</li></ol>';dialog.showModal()}));}
